import sympy as sp

# Top-level setup
x, y, z = sp.symbols('x y z')
I2 = sp.eye(2)
I3 = sp.eye(3)
O2 = sp.zeros(2, 2)
O3 = sp.zeros(3, 3)

def conditions(witness):
    """
    Checks if the witness is a valid counterexample.
    The witness should be a matrix in GL_n(R) that is not in GE_n(R).
    """
    # H_1: Let n be a positive integer
    try:
        h1 = isinstance(witness, sp.Matrix) and witness.shape[0] == witness.shape[1] and witness.shape[0] > 0
    except Exception:
        h1 = False

    # neg_Q: GL_n(R) is NOT generated by elementary matrices together with invertible diagonal matrices
    try:
        if not h1:
            neg_q = False
        else:
            n = witness.shape[0]
            det = sp.simplify(witness.det())
            
            # Check if the matrix is in GL_n(R) (determinant is a unit)
            is_unit = False
            if det.free_symbols:
                if det.is_constant() and det != 0:
                    is_unit = True
            else:
                try:
                    c = complex(sp.N(det))
                    n_det = c.real**2 + c.imag**2
                    # Units in typical numerical counterexample rings (like Z[sqrt(-5)]) have norm 1
                    if abs(n_det - 1) < 1e-9:
                        is_unit = True
                except Exception:
                    pass
                    
            if not is_unit:
                neg_q = False
            else:
                # Check if the matrix is NOT in GE_n(R)
                # We verify this by checking if a 2x2 matrix is "stuck" (cannot be reduced by elementary operations)
                if n != 2:
                    neg_q = False
                else:
                    is_poly = any(val.free_symbols for val in witness)
                    if is_poly:
                        # Polynomial matrix check (e.g., Cohn's matrix over k[x,y])
                        def lt_divides(p1, p2):
                            p1 = sp.expand(p1)
                            p2 = sp.expand(p2)
                            if p1 == 0: return False
                            if p2 == 0: return True
                            if not p1.free_symbols: return True
                            if not p2.free_symbols: return False
                            try:
                                poly1 = sp.Poly(p1)
                                poly2 = sp.Poly(p2)
                                if poly1.gens != poly2.gens:
                                    gens = list(set(poly1.gens) | set(poly2.gens))
                                    poly1 = sp.Poly(p1, *gens)
                                    poly2 = sp.Poly(p2, *gens)
                                lm1 = poly1.LM()
                                lm2 = poly2.LM()
                                return all(e1 <= e2 for e1, e2 in zip(lm1, lm2))
                            except Exception:
                                return False
                                
                        stuck = True
                        for i in range(2):
                            for j in range(2):
                                if sp.simplify(witness[i, j]) == 0:
                                    stuck = False
                        if stuck:
                            # If any row/col can potentially be reduced by another, it might not be stuck
                            if lt_divides(witness[1,0], witness[0,0]) or lt_divides(witness[1,1], witness[0,1]): stuck = False
                            elif lt_divides(witness[0,0], witness[1,0]) or lt_divides(witness[0,1], witness[1,1]): stuck = False
                            elif lt_divides(witness[0,1], witness[0,0]) or lt_divides(witness[1,1], witness[1,0]): stuck = False
                            elif lt_divides(witness[0,0], witness[0,1]) or lt_divides(witness[1,0], witness[1,1]): stuck = False
                        neg_q = stuck
                    else:
                        # Numerical matrix check (e.g., over Z[sqrt(-5)])
                        def norm(val):
                            try:
                                c = complex(sp.N(val))
                                return c.real**2 + c.imag**2
                            except Exception:
                                return float('inf')
                                
                        stuck = True
                        if any(norm(val) < 1e-9 for val in witness):
                            stuck = False
                            
                        if stuck:
                            qs = [0, 1, -1, 2, -2, 3, -3]
                            rads = set()
                            for val in witness:
                                for arg in sp.preorder_traversal(val):
                                    if isinstance(arg, sp.Pow) and arg.exp == sp.Rational(1, 2):
                                        rads.add(arg)
                            q_cands = list(qs)
                            for r in rads:
                                for a in qs:
                                    for b in qs:
                                        if b != 0:
                                            q_cands.append(a + b * r)
                                            
                            def can_reduce_row(r_target, r_sub):
                                n_orig = norm(r_target[0]) + norm(r_target[1])
                                for q in q_cands:
                                    n_new = norm(r_target[0] - q * r_sub[0]) + norm(r_target[1] - q * r_sub[1])
                                    if n_new < n_orig - 1e-9:
                                        return True
                                return False
                                
                            if can_reduce_row((witness[0,0], witness[0,1]), (witness[1,0], witness[1,1])): stuck = False
                            elif can_reduce_row((witness[1,0], witness[1,1]), (witness[0,0], witness[0,1])): stuck = False
                            elif can_reduce_row((witness[0,0], witness[1,0]), (witness[0,1], witness[1,1])): stuck = False
                            elif can_reduce_row((witness[0,1], witness[1,1]), (witness[0,0], witness[1,0])): stuck = False
                            
                        neg_q = stuck
    except Exception:
        neg_q = False

    return [h1, neg_q]

CONDITION_LABELS = [
    "H_1: n is a positive integer",
    "¬Q: GL_n(R) is not generated by elementary matrices together with invertible diagonal matrices"
]

N_HYP = 1
NEG_Q_INDEX = 1